changeSet.sql:

ALTER TABLE fuel_types
    ADD CONSTRAINT fuel_types_ck1 CHECK (
        code IN ('DIESEL', 'AI_92', 'AI_95')
        AND
        sort_order >= 0
    );


ALTER TABLE source_publications
    ADD CONSTRAINT source_publications_ck1 CHECK (
        content_hash ~ '^[0-9a-f]{64}$'
    );


ALTER TABLE regional_price_keys
    ADD CONSTRAINT regional_price_keys_ck1 CHECK (
        provider_code IN ('ROSSTAT', 'RUSTATA', 'WHEREFUEL')
    );


ALTER TABLE archive_state
    ADD CONSTRAINT archive_state_ck1 CHECK (
        id = 1
        AND
        revision >= 1
    );
